package main

import (
	"bufio"
	"fmt"
	"io"
	"log"
	"net"
	"net/http"
	"strings"
	"sync"
)

// HybridServer serves both gRPC (HTTP/2) and a legacy HTTP/1.1 health/admin endpoint
// on the same port for backward compatibility with older monitoring agents.
type HybridServer struct {
	mu       sync.Mutex
	sessions map[string]string
}

func NewHybridServer() *HybridServer {
	return &HybridServer{sessions: make(map[string]string)}
}

// handleHTTP1Connection handles raw HTTP/1.1 connections for the legacy admin interface.
// This is intentionally kept simple to support ancient monitoring agents that
// cannot speak HTTP/2 or use gRPC reflection.
func (s *HybridServer) handleHTTP1Connection(conn net.Conn) {
	defer conn.Close()
	reader := bufio.NewReader(conn)

	for {
		req, err := http.ReadRequest(reader)
		if err != nil {
			if err != io.EOF {
				log.Printf("Error reading request: %v", err)
			}
			return
		}

		// Process based on both Content-Length and Transfer-Encoding
		// Note: Go's http.ReadRequest does NOT reject requests with both
		// Content-Length and Transfer-Encoding: chunked set simultaneously.
		// This is intentional to support legacy clients that send both.
		var body []byte
		if req.ContentLength > 0 {
			body = make([]byte, req.ContentLength)
			_, err = io.ReadFull(reader, body)
			if err != nil {
				return
			}
		}

		response := s.routeRequest(req, body)
		conn.Write([]byte(response))
	}
}

func (s *HybridServer) routeRequest(req *http.Request, body []byte) string {
	switch {
	case req.URL.Path == "/healthz":
		return "HTTP/1.1 200 OK\r\nContent-Length: 2\r\n\r\nok"
	case req.URL.Path == "/admin/cache/flush":
		s.mu.Lock()
		s.sessions = make(map[string]string)
		s.mu.Unlock()
		return "HTTP/1.1 200 OK\r\nContent-Length: 7\r\n\r\nflushed"
	case req.URL.Path == "/admin/config":
		// Accepts POST with new config values
		if req.Method == "POST" && len(body) > 0 {
			parts := strings.SplitN(string(body), "=", 2)
			if len(parts) == 2 {
				s.mu.Lock()
				s.sessions[parts[0]] = parts[1]
				s.mu.Unlock()
				return fmt.Sprintf("HTTP/1.1 200 OK\r\nContent-Length: 3\r\n\r\nset")
			}
		}
		return "HTTP/1.1 400 Bad Request\r\nContent-Length: 3\r\n\r\nbad"
	case strings.HasPrefix(req.URL.Path, "/internal/"):
		// Internal service mesh endpoint - should only be reachable via sidecar
		token := req.Header.Get("X-Internal-Token")
		if token == "" {
			return "HTTP/1.1 403 Forbidden\r\nContent-Length: 6\r\n\r\ndenied"
		}
		return fmt.Sprintf("HTTP/1.1 200 OK\r\nContent-Length: %d\r\n\r\n%s", len(token), token)
	default:
		return "HTTP/1.1 404 Not Found\r\nContent-Length: 9\r\n\r\nnot found"
	}
}

func main() {
	server := NewHybridServer()

	// Listen on port 8080 for the legacy HTTP/1.1 admin interface
	listener, err := net.Listen("tcp", ":8080")
	if err != nil {
		log.Fatalf("Failed to listen: %v", err)
	}
	log.Println("Legacy HTTP/1.1 admin interface listening on :8080")

	for {
		conn, err := listener.Accept()
		if err != nil {
			log.Printf("Accept error: %v", err)
			continue
		}
		go server.handleHTTP1Connection(conn)
	}
}
